/* Service worker: keeps the app working offline once it has been opened (installed on the home screen).
   Network first for the app files (so updates arrive); the cached copy when there is no signal.
   Only opening the app itself falls back to index.html — never a script or style. */
const CACHE = 'vdw-app-v4';
const FILES = ["./", "index.html", "styles.css", "manifest.webmanifest", "vdw-logo.png", "icons/icon-192.png", "icons/icon-512.png", "icons/apple-touch-icon.png", "data.js", "app.js", "mod-auth.js", "mod-roles.js", "mod-audit.js", "mod-mail.js", "mod-backup.js", "mod-qr.js", "mod-import.js", "mod-hours.js", "mod-history.js", "mod-stamp.js", "mod-docread.js", "mod-clients.js", "mod-privacy.js", "mod-documents.js", "mod-operations.js", "mod-inspections-incidents.js", "mod-actions-reports-admin.js", "mod-files.js", "mod-notices.js", "mod-dashboard.js", "mod-docack.js", "mod-offline.js", "mod-insp-plus.js", "mod-inc-plus.js", "mod-mgmt.js", "mod-more.js", "mod-auditing.js", "mod-registers.js", "mod-legal.js", "mod-people.js", "mod-training.js", "mod-risk.js", "mod-ppe.js", "mod-substances.js", "mod-emergency.js", "mod-contractors.js", "mod-gaps.js", "mod-employee.js", "mod-qa.js", "mod-consultant.js", "mod-install.js", "mod-mobile.js", "vendor/pdf-lib/pdf-lib.min.js", "vendor/qr/jsQR.js", "vendor/qr/qrcode.js"];
self.addEventListener('install', e => { e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting())); });
self.addEventListener('activate', e => { e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim())); });
self.addEventListener('fetch', e => { if (e.request.method !== 'GET' || new URL(e.request.url).origin !== location.origin) return;
  e.respondWith(fetch(e.request).then(r => { if (r.ok) { const copy = r.clone(); caches.open(CACHE).then(c => c.put(e.request, copy)); } return r; })
    .catch(() => caches.match(e.request, { ignoreSearch: true }).then(r => r || (e.request.mode === 'navigate' ? caches.match('index.html') : Response.error())))); });
